<script setup lang="js">
import { ref, onMounted, onUnmounted, computed, nextTick } from 'vue';
import { useRoute } from 'vue-router'

const route = useRoute()

const isActive = (path) => {
  return route.path === path
}

const activeSection = ref(''); // Stores the currently visible section
const isMenuOpen = ref(false);
const isScrolled = ref(false); // Indicates if the user has scrolled down

// Toggle menu open/close logic
const toggleMenu = async () => {
  const menuNavigation = document.querySelector('.menuMobile-navigation');

  if (isMenuOpen.value) {
    // Trigger closing animation if menu is open
    menuNavigation.classList.add('closing');

    setTimeout(() => {
      isMenuOpen.value = false;
      menuNavigation.classList.remove('open', 'closing');
    }, 900);
  } else {
    // Open menu
    isMenuOpen.value = true;
    await nextTick();
    menuNavigation.classList.add('open');
  }
};

const closeMenu = () => {
  const menuNavigation = document.querySelector('.menuMobile-navigation');
  menuNavigation.classList.add('closing');

  setTimeout(() => {
    isMenuOpen.value = false;
    menuNavigation.classList.remove('open', 'closing');
  }, 900);
};

// Class for menu based on active section
const menuClass = computed(() => {
  return activeSection.value === 'darkBg' ? 'dark' : 'white';
});

// Update active section based on scroll position
const updateActiveSection = async () => {
  const menuHeight = document.querySelector('nav.wrapper').offsetHeight;
  const scrollPosition = window.scrollY + menuHeight - 50;

  document.querySelectorAll('.darkBg, .whiteBg').forEach((section) => {
    const sectionType = section.classList.contains('darkBg') ? 'darkBg' : 'whiteBg';
    const sectionTop = section.offsetTop;
    const sectionBottom = sectionTop + section.offsetHeight;

    if (scrollPosition >= sectionTop && scrollPosition < sectionBottom) {
      if (activeSection.value !== sectionType) {
        activeSection.value = sectionType;
      }
    }
  });

  await nextTick();
};

// Detect if the user has scrolled
const handleScroll = () => {
  isScrolled.value = window.scrollY > 0;
};

// Dynamic classes for the wrapper and cliquable
const wrapperClass = computed(() => ({
  scrolled: isScrolled.value, // Adds the "scrolled" class when scrolling
}));

const olClass = computed(() => ({
  scaled: isScrolled.value, // Adds the "scaled" class when scrolling
}));

onMounted(() => {
  window.addEventListener('scroll', handleScroll);
  window.addEventListener('scroll', updateActiveSection);

  const intervalId = setInterval(updateActiveSection, 100);
  updateActiveSection();

  onUnmounted(() => {
    window.removeEventListener('scroll', handleScroll);
    window.removeEventListener('scroll', updateActiveSection);
    clearInterval(intervalId);
  });
});
</script>
