<style scoped>
.wrapper {
  display: flex;
  justify-content: space-between;
  width: 100vw;
  position: fixed;
  top: 0;
  margin-top: 15px;
  z-index: 9999;
  align-items: center;
  transition: all 0.3s ease-in-out;
  ol {
    grid-column: 1/4;

    .logo {
      position: relative;
      z-index: 9999;
    }
  }

  ul {
    grid-column: 5/13;
    display: flex;
    justify-content: space-between;
    gap: 25px;
    list-style: none;
    .line {
      display: block;
      border-radius: 100px;
      background: var(--tertiary-color);
      width: 2px;
      height: 33px;
      max-width: 2px;
      margin-top: -3px;
    }

    .texte {
      font-family: "Lexend Tera", sans-serif;
      font-size: 20px;
      font-style: normal;
      font-weight: 800;
      line-height: 0; /* 0% */
      transition: color 0.5s ease-in-out;
    }
    .texte.active {
      color: var(--tertiary-color);
    }
  }
}

.cliquable {
  transform: scale(1);
  transition: transform 0.3s ease-in-out;
}

/* Quand on scroll */
.cliquable.scaled {
  transform: scale(0.7); /* Réduit l'échelle */
}

/* Mobile menu styling */
.menuMobile {
  display: none !important;
}

@media screen and (max-width: 900px) {
  svg {
    z-index: 9999;
    cursor: pointer;
  }

  .logo {
    width: 70%;
  }

  .cliquable {
    z-index: 1;
    position: relative
  }

  /* Hide desktop menu and display mobile menu */
  .menuDesktop {
    display: none !important;
  }

  .menuMobile {
    display: block !important;
    .menuMobile-burger {
      display: flex;
      flex-direction: column;
      gap: 5px;
      align-items: center;
      justify-content: center;
    }

    /* Mobile navigation with clip-path effect */
    .menuMobile-navigation {
      position: absolute;
      top: 0;
      right: 0;
      clip-path: circle(0% at 100% 0);
      transition: clip-path 0.6s ease-in;
      background: var(--color-secondary);
      height: 100vh;
      width: 100vw;
      margin-top: -15px;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 33px;

      .line {
        display: block;
        border-radius: 100px;
        background: none;
        width: 0;
        height: 0;
        max-width: none;
        margin-top: 0;
      }

      a {
        color: var(--color-primary);
        text-align: center;
        font-family: "Lexend Tera", sans-serif;
        font-size: clamp(39px, 39px + 0.0487 * (100vw - 366px), 65px);
        font-style: normal;
        font-weight: 800;
        line-height: 0; /* 0% */
        text-transform: uppercase;
      }
    }

    .menuMobile-navigation.open {
      clip-path: circle(150% at top right); /* Expanded state (visible) */
    }

    .menuMobile-navigation.closing {
      clip-path: circle(0% at 100% 0);
      transition: clip-path 0.6s ease-in; /* Durée de transition alignée */
    }
  }

  /* Menu item and line animations */
  .menuMobile-navigation li {
    height: 69px;
    overflow: hidden;
    position: relative;
  }

  .menuMobile-navigation li a {
    position: relative;
    bottom: -120px;
    transition: bottom 0.4s ease-in-out 0.5s; /* Animation delay */
  }

  .menuMobile-navigation.open li a {
    bottom: -35px; /* Slide in to visible position */
  }

  .menuMobile-navigation .line {
    transition: width 0.4s ease-in-out 0.5s;
  }

  .menuMobile-navigation.open .line {
    background: var(--color-primary);
    display: block;
    width: 162px; /* Target width */
    height: 3px;
  }

  .menuMobile-navigation.closing li a {
    bottom: -120px; /* Slide out to hidden position */
    transition: bottom 0.4s ease-in-out; /* Disappear animation */
  }

  .menuMobile-navigation.closing .line {
    width: 0;
    height: 0;
    transition: width 0.4s ease-in-out; /* Shrink animation */
  }
}
